-- Scripts Practice 6 — PostgreSQL-only version

BEGIN;

-- Drop in dependency order
DROP TABLE IF EXISTS project;
DROP TABLE IF EXISTS employee CASCADE;

-- ======================================================================
-- Table definitions
-- ======================================================================

CREATE TABLE employee (
  empid       integer PRIMARY KEY,
  prefix      text,
  first_name  text,
  last_name   text,
  gender      char(1) CHECK (gender IN ('M','F')),
  email       text,
  father_name text,
  mother_name text,
  age         numeric(5,2),
  weight      numeric(6,2),
  salary      numeric(12,2),
  phone       text,
  city        text,
  state       text,
  zip         integer,
  user_name   text,
  password    text,
  position    text
);

CREATE TABLE project (
  empid      integer NOT NULL REFERENCES employee(empid) ON DELETE CASCADE,
  project    text NOT NULL,
  start_date text,
  end_date   text,
  p_manager  text,
  PRIMARY KEY (empid, project)
);

