-- ======================================================================
-- Views (PostgreSQL)
-- ======================================================================

-- 1) staff: quick access to identity fields
CREATE OR REPLACE VIEW staff AS
SELECT empid, first_name, last_name, gender
FROM employee;

-- DROP VIEW staff;

-- 2) prof_high_salary: employees with prefix like 'Prof' and salary above average

CREATE OR REPLACE VIEW prof_high_salary AS
SELECT empid, first_name, last_name, gender, position
FROM employee
WHERE -- complete this part

-- 3) young_25: employees with age < 25; WITH CHECK OPTION ensures writes via the view respect the predicate
CREATE OR REPLACE VIEW young_25 AS
SELECT empid, first_name, last_name, gender, age, position
FROM employee
WHERE age < 25
WITH LOCAL CHECK OPTION;

-- INSERT INTO young_25 (empid, first_name, last_name, gender, age, position)
-- VALUES (10000, 'John', 'Smith', 'M', 30, 'Analyst');

-- 4) project_emp: details for employees on the GIS Project
--    The original used a pattern; we keep a case-insensitive match.
CREATE OR REPLACE VIEW project_emp AS
SELECT e.empid, e.first_name, e.email, e.age, e.phone, e.position, e.city
FROM -- complete this part


