-- 5) Employees who are neither Team Lead, nor Research Assistant, nor HR Director.
--    (Using a subquery, as requested.)
SELECT *
FROM employee e
WHERE NOT EXISTS (
  SELECT 1
  FROM (VALUES ('Team Lead'), ('Research Assistant'), ('HR Director')) AS disallowed(pos)
  WHERE e.position ILIKE '%' || pos || '%'
)
ORDER BY city;

