-- 1) Show the average salary for each city with at least 20 employees, order the results by average salary in descending order.

SELECT
    city,
    COUNT(*) AS num_employees,
    AVG(salary) AS avg_salary
FROM employee
GROUP BY city
HAVING COUNT(*) >= 3          -- only keep groups with 2+ employees
ORDER BY avg_salary DESC;     -- sort highest average salary first

-- 2) Find employees whose salary is higher than the average salary in their city.

WITH city_avg AS (
    SELECT city, AVG(salary) AS avg_salary
    FROM employee
    GROUP BY city
)
-- use CTE above in query

-- 3) List employees who live in NV or TX

SELECT empid, first_name, last_name, state
FROM employee
WHERE state = 'NV'
UNION
SELECT empid, first_name, last_name, state
FROM employee
WHERE state = 'TX'
ORDER BY state, last_name, first_name;

-- OR

SELECT empid, first_name, last_name, state
FROM employee
WHERE state = 'NV' OR state = 'TX'
ORDER BY state, last_name, first_name;

