WHERE -- complete using subquery

-- 6) Show 5 employee’s name in uppercase and how long their email address is

SELECT
    UPPER(first_name || ' ' || last_name) AS full_name_upper,
    LENGTH(email) AS email_length
FROM employee
LIMIT 5;


-- 7) Rank employees within each state based on their salary, with the highest salary getting rank 1

SELECT
    empid,
    first_name,
    last_name,
    state,
    salary,
    RANK() -- continue from here

-- 8) Find employees whose email ends with @gmail.com

SELECT
    empid,
    first_name,
    last_name,
    email
FROM employee 
WHERE email ~* '@gmail\.com$'; -- ~* means  REGEXP_LIKE  (case-insensitive) in postgres






